from questions._util import q

QUESTIONS = [
    q("ctr-rootless", "medium", "Docker 1.10 could remap container root off host root with user namespaces. What did a stock upgrade not do?", "Turn the feature on for the daemon.", "Create subordinate UID ranges for root.", "Remap containers that already existed.", "Apply the remap to volumes on the host.", "The daemon config had to change, in a systemd drop-in so package upgrades would not wipe it. An isolation layer that is off is not protecting you."),
    q("ctr-rootless", "hard", "Why do user namespaces make container root harder to turn into host root?", "Container UID 0 maps to an unprivileged host UID.", "They strip every capability from UID 0 in it.", "They block the syscalls that change UIDs.", "They give the container its own kernel keyring.", "The mapping is the control. Privileged mode and a mounted runtime socket throw it away."),
    q("ctr-networks", "medium", "What is Docker's default 'bridge' network really?", "NAT behind a private bridge.", "A macvlan on the host's subnet.", "A direct attach to the host NIC.", "An overlay between Docker hosts.", "Containers are not on the host LAN until you choose a mode that puts them there. That is why inbound services need an explicit publish."),
    q("ctr-networks", "hard", "Why was macvlan added to Docker?", "To put containers on the host's L2 network.", "To share the host's network namespace.", "To encrypt traffic between Docker hosts.", "To give containers IPv6 by default.", "What Docker calls bridged is NAT. Macvlan gives each container its own MAC on the LAN, without the NAT hop."),
    q("ctr-networks", "easy", "Why are published ports a poor fit for a service that picks its ports at runtime?", "Host ports are fixed when the container starts.", "Docker forwards only ports declared with EXPOSE.", "Published ports must be lower than 32768.", "NAT rewrites the port the service picked.", "A port chosen later is not forwarded. Dynamic ports need host networking or a proxy that learns the port, not a static -p you guessed."),
    q("ctr-compose", "medium", "Early Compose could not declare a data directory shared by every service. What fixed that?", "Named volumes declared in the file.", "Links between the services.", "volumes_from on each service.", "A shared network for the services.", "Links gave DNS names, not a common writable directory. Top-level named volumes let services mount the same data."),
    q("k8s-debug", "hard", "An old default kubelet API reachable from the pod network was enough to control the node. Why?", "It ran commands in pods, with no auth.", "It returned the node's SSH host keys.", "It proxied requests to etcd unauthenticated.", "It let callers edit the node's taints.", "The kubelet runs the containers. An unauthenticated kubelet port is a remote control for that node and, through it, the cluster."),
    q("obs-metrics", "medium", "What does an unauthenticated cAdvisor on port 4194 tell a compromised container?", "What else runs on the node.", "The node's kubelet credentials.", "The secrets of other pods.", "Only its own cgroup's usage.", "Container names, images, and resource use are reconnaissance. Bind it to localhost or put it behind auth."),
    q("ctr-images", "medium", "How do Docker Hub automated builds keep an image fresh?", "Hub rebuilds it from the linked git repo.", "Hub patches its packages in place on scan.", "Hub rebuilds it when the base gets a CVE.", "Hub re-tags it to the newest base image.", "An unmaintained image is a frozen set of packages. Automated build is how the author keeps it moving, not a patch service."),
    q("ctr-images", "hard", "Outside the official images, what is Docker Hub's stance on maintenance?", "The publisher owns it entirely.", "Hub rebuilds popular images.", "Hub removes images with CVEs.", "Verified publishers get patches.", "Hub does not patch or vouch for community images, and a high pull count says nothing about age. Check the Dockerfile before you run a search hit."),
    q("ctr-security", "medium", "A cluster refuses root containers. How can ping still work in a non-root image?", "setcap cap_net_raw on the real binary.", "setcap cap_net_admin on the binary.", "Make the ping binary setuid root.", "Add the user to the netdev group.", "The capability must also be in the runtime's allowed set. setcap does not follow a symlink, so point it at the real binary. A non-root, no-new-privileges policy blocks setuid."),
    q("linux-permissions", "easy", "getcap on a file shows cap_net_raw+ep. What does +ep mean?", "Effective and permitted.", "Effective and preserved.", "Enabled and propagated.", "Exempt and privileged.", "The binary can use the capability. File capabilities are how a non-root binary gets one privilege, and how a non-root image smuggles it in."),
    q("k8s-rbac", "medium", "Kubernetes has no built-in user database. Where must an access review start?", "With the authenticators the cluster uses.", "With kubectl get users across namespaces.", "With the user accounts on the control plane.", "With the ServiceAccounts in kube-system.", "OIDC, certificates, or a cloud IAM webhook decide who exists. If you are not on RBAC, 'who is admin' may be 'anyone who can authenticate'."),
    q("k8s-rbac", "hard", "Why does the bind verb on roles matter?", "It lets you grant roles you do not hold yourself.", "It lets you bind roles across namespaces.", "It lets you bind roles to unauthenticated users.", "It lets you create new roles in a namespace.", "Without bind, RBAC stops you granting more than you have. escalate, bind, and impersonate turn a limited account into a broader one. Audit them on purpose."),
    q("sec-pki", "medium", "What does a public Kubernetes API certificate often leak?", "Internal names and IPs in its SAN.", "The cluster's version in its subject.", "The service account signing key.", "The node list in its issuer field.", "The API cert lists what the control plane calls itself. Internet scanners find clusters by it. Do not put the API on the internet unless you mean to."),
    q("sec-pki", "hard", "Why are basic auth and static tokens a poor cluster login?", "Cleartext on disk, and changes need a restart.", "They expire every hour and break automation.", "They cannot be bound to RBAC roles.", "They only work over plain HTTP.", "Certificates avoid the password file but add the revocation problem: a lost client cert stays valid until it expires."),
    q("sec-pki", "medium", "A vanilla cluster typically has several CAs. What is the main API CA for?", "Authenticating clients to the API server.", "Signing serving certs for Ingress hosts.", "Encrypting Secrets at rest in etcd.", "Signing tokens for service accounts.", "Mixing CAs, especially giving etcd certs from the general Kubernetes CA, widens who can read the database."),
    q("ctr-containerd", "easy", "containerd plus runc can run a container without dockerd. What is ctr?", "containerd's own CLI.", "The CRI's debug CLI.", "runc's management CLI.", "Docker's low-level CLI.", "You do not need the Docker daemon to have an OCI container. You do need to know which CLI owns the socket you are debugging. crictl is the CRI tool."),
    q("ctr-security", "medium", "Docker 18.09 lets a client reach a remote daemon over SSH. What does that avoid?", "Exposing a TCP port with its own TLS CA.", "Running a daemon on the remote host.", "Granting the remote user docker group.", "Copying images to the remote host.", "SSH reuses host login and the daemon's local socket permissions. It is the better remote default."),
    q("ctr-security", "hard", "Why put a reverse proxy in front of the Docker API to give a monitor stats?", "The daemon has no per-call authorization.", "The daemon only serves stats over TLS.", "The proxy caches stats to protect the daemon.", "The daemon rejects non-root socket clients.", "The API is HTTP. A proxy can allow GET of container JSON and refuse everything else, a policy the daemon does not have."),
    q("ctr-runtime", "medium", "Podman and Docker can both use runc. What is the key operational difference?", "Podman needs no root daemon, and stores are per user.", "Podman builds images faster with a shared cache.", "Podman runs pods, which Docker cannot run.", "Podman uses crun, which isolates better.", "sudo podman is a different store from podman. Rootless and rootful do not see each other's images."),
    q("ctr-ports", "easy", "Why is rootful Podman sometimes chosen over rootless?", "Low ports and networking behave differently.", "Rootless Podman cannot pull private images.", "Rootless Podman cannot run Compose files.", "Rootful Podman shares the user's image store.", "The image store is separate too. Know which one you are debugging before you conclude an image 'is not there'."),
    q("sec-image", "medium", "What does scanning an image for OS CVEs depend on?", "The distro's package database in the image.", "The image's labels, which list the packages.", "The registry's metadata about the image.", "The build logs of the image's last build.", "A scanner that does not understand that distro reports a false empty. Windows images, language packages, and distroless images each break a naive scanner differently."),
    q("k8s-services", "hard", "Why can a host on the nodes' LAN sometimes reach pod IPs you thought were private?", "Nodes forward traffic for pod CIDRs.", "Pod IPs come from the node's subnet.", "kube-proxy publishes pod IPs over ARP.", "The overlay advertises routes via BGP.", "'Not advertised' is not 'not routable'. Add a route via a node and it forwards. Test from the node LAN before you call the pod network unreachable."),
    q("cloud-compute", "medium", "Many managed Kubernetes products put the API server on the internet by default. What should you do?", "Turn public access off if you don't need it.", "Rely on RBAC, since anonymous calls fail.", "Move the API server to a non-standard port.", "Hide the version banner from responses.", "The certificate and version banner are enough for the internet to find you. Exposure is the common case, not the exception."),
    q("k8s-debug", "easy", "Which ports typically reveal a Kubernetes cluster on a network scan?", "6443, 10250, 2379", "8080, 9090, 3000", "443, 8443, 9443", "22, 53, 179", "API 6443 or 443, kubelet 10250, and etcd 2379 and 2380. 10255 is the old unauthenticated kubelet read-only port. If it is open, treat it as a finding."),
    q("k8s-secrets", "medium", "ServiceAccounts used to get a long-lived token Secret automatically. Why did bound tokens replace that?", "They are per pod, expire, and have an audience.", "They are encrypted, while the Secrets were not.", "They are stored in the kubelet, not etcd.", "They work across clusters for federation.", "A legacy token lives until someone deletes the Secret. If you still see type kubernetes.io/service-account-token, you are on the old pattern."),
    q("k8s-rbac", "hard", "Cloud Kubernetes often chains RBAC with a webhook authorizer. When is a request allowed?", "When any authorizer in the chain allows it.", "When every authorizer in the chain allows it.", "When RBAC allows it, then the webhook audits.", "When the webhook allows it, then RBAC checks.", "Authorizers are consulted in --authorization-mode order, and the first allow wins. An audit that only reads RoleBindings misses the cloud IAM allow."),
    q("k8s-rbac", "medium", "MicroK8s ships with RBAC off until you enable the addon. What is the consequence?", "Any authenticated user is effectively admin.", "Only cluster-admin can use the API at all.", "ServiceAccounts cannot call the API.", "Anonymous users get read-only access.", "Do not assume kubeadm defaults. 'Kubernetes is secure by default' is not a sentence you can say once for every distribution."),
    q("sec-runtime", "medium", "Windows process-isolated containers share a kernel. What about Hyper-V isolated ones?", "Each runs in its own utility VM.", "They share a kernel but not a registry.", "They run as host processes with ACLs.", "They share a VM with every other pod.", "The boundary is closer to a virtual machine. Host-process containers go the other way: they are not isolated from the host process space."),
    q("sec-runtime", "hard", "Why is there no simple yes to 'do containers still contain'?", "Kernel bugs are container escapes.", "Seccomp is off in most runtimes.", "cgroups do not limit kernel memory.", "Namespaces cannot hide host files.", "A shared Linux kernel is a large attack surface. A VM runtime or a sandbox is the choice when the neighbor workload is not trusted."),
    q("sec-runtime", "medium", "For a regulated Kubernetes platform, what does runtime security decide?", "When to use a sandbox or VM-based runtime.", "Which syscalls each workload may make.", "Which capabilities to drop from each pod.", "Which processes runtime tools should flag.", "Workload security limits what a normal container may do. Runtime security is the isolation technology under it."),
    q("k8s-resources", "medium", "A container is a process on a shared kernel. What happens without limits?", "One pod can starve the node, even with a fork bomb.", "The kubelet assigns each pod a default share.", "The scheduler refuses to place the pod.", "Pods are evicted as soon as usage rises.", "Set CPU, memory, and a PID limit. Without them, one pod can take the node down."),
    q("ctr-images", "easy", "How do you patch a containerized app?", "Build a new image and roll it out.", "Run apt upgrade in each container.", "Restart pods so they re-pull the tag.", "Patch the base layer in the registry.", "The running container is disposable. The image is the patch. A restart only gets a new image if the tag moved."),
    q("k8s-psa", "medium", "Why does image build guidance for Kubernetes start with the user the process runs as?", "Root is the default unless built and enforced.", "Non-root images pull faster on most nodes.", "USER in the image overrides runAsUser.", "Root images cannot be signed with cosign.", "Build a non-root user and enforce it at admission, so a later manifest cannot put root back. The pod spec overrides the image's USER."),
    q("cloud-registry", "medium", "In a Kubernetes patch path, what is the registry?", "Where new images must land before rollout.", "Optional, since nodes keep old images.", "A cache of the images built in CI.", "Where the cluster stores its manifests.", "Losing the registry stops updates. Authenticate push and pull separately. A cluster that can push to its own registry can replace what it runs."),
    q("iac-workflow", "easy", "Why is version management easier once the platform is YAML and HCL?", "You can diff, review, and recreate it.", "Files cannot drift from the cluster.", "Live state no longer needs a backup.", "Changes no longer need a pipeline.", "The files are the source only if a controller or a pipeline actually applies them."),
    q("sec-bench", "medium", "Why must a Kubernetes configuration standard be written down?", "Distributions differ in their defaults.", "kube-bench needs a file to compare to.", "The API server reads it at start-up.", "Admission webhooks load it by name.", "CIS benchmarks and Pod Security are starting points. Then you say which one you enforce. The standard plus a check, not a hope."),
    q("k8s-netpol", "hard", "PCI segmentation keeps systems of different sensitivity apart. On one cluster, what achieves it?", "NetworkPolicy, dedicated nodes, or clusters.", "A namespace per sensitivity level.", "RBAC limiting who deploys to each.", "A separate Ingress class per sensitivity level.", "A namespace label alone does not segment traffic. If cardholder pods can connect to everything else, they are not segmented."),
    q("sec-audit", "medium", "Kubernetes audit logging is off until enabled. On a managed cluster, how do you set it?", "Through the provider's console or API.", "By editing the API server's manifest.", "By adding a flag to each kubelet.", "By deploying an audit DaemonSet.", "You often cannot pass --audit-policy-file yourself, and GKE, EKS, and AKS differ. A policy that logs nothing ticks the box and misses the incident."),
    q("obs-logs", "hard", "Why are container logs collected only on the node incomplete?", "Pods move, and node logs die with the node.", "The kubelet truncates stdout at 1MiB.", "kubectl logs only shows the last hour.", "stdout is buffered until the pod exits.", "Ship stdout off the node. Design for ephemeral pods, not for a syslog file on one VM."),
    q("k8s-secrets", "easy", "Why not put a database password in the image?", "Images are widely copied and readable.", "Images are too large to update quickly.", "Secrets in layers break the build cache.", "Kubernetes strips env from image config.", "A password change would also force a rebuild. Inject it at runtime, and the image stays one artifact for every environment."),
    q("k8s-workloads", "medium", "Workload security starts from what a container is. What is it?", "A process isolated by kernel features.", "A lightweight VM with a shared kernel.", "A sandboxed process with its own kernel.", "A chroot with resource limits applied.", "It runs as root unless the image and pod say otherwise. Drop capabilities, run non-root, and add seccomp. Those are not a hypervisor."),
    q("net-cloud", "medium", "Kubernetes networking is delegated to a CNI. What does overlay mode mean?", "Pod traffic is encapsulated between nodes.", "Pods get IPs from the node's own subnet.", "Pods share the IP address of their node.", "Pod traffic is routed with BGP to the LAN.", "Pod IPs are a separate range, not host LAN addresses. Underlay mode puts pods on the physical network, which changes the packet path and the firewall you need."),
    q("k8s-rbac", "easy", "How can two certified Kubernetes distributions still differ?", "In security defaults such as auth and audit.", "In which core API objects they support.", "In the kubectl commands they accept.", "In the YAML format of the manifests.", "Conformance tests behavior, not a security baseline. Ask which product you are on before you copy a hardening guide written for kubeadm."),
    q("sec-bench", "easy", "The PCI container guidance is vendor neutral. What do you still have to do?", "Map each item to your platform's features.", "Pick a certified vendor to implement it.", "Wait for a Kubernetes-specific version.", "Run the official PCI scanner against it.", "The useful table is threats and practices. The work is saying which feature, such as Pod Security, RBAC or a CNI, meets each row."),
    q("obs-metrics", "medium", "kube-proxy's health endpoint listens on 0.0.0.0:10256. What is true of it?", "It needs no auth and returns metadata.", "It needs a client cert from the cluster CA.", "It is reachable only from localhost.", "It returns a bare ok and nothing else.", "/healthz returns metadata, and the root path 404s. An open health port is a discovery aid. Know which ports on your nodes are unauthenticated."),
    q("sec-audit", "hard", "What does a reachable Go pprof endpoint on a Kubernetes component give away?", "Profiles of the process's internals.", "A shell inside the component's container.", "Write access to the component's flags.", "The component's TLS private key file.", "It is a debugging server meant for developers. Treat debug and profile ports like admin ports. Do not expose them on a node address."),
    q("k8s-storage", "medium", "What does CVE-2025-1767 in gitRepo volumes let a pod do?", "Read other git repos on the node.", "Run commands in other pods on the node.", "Write to the node's kubelet config.", "Clone private repos with the node's key.", "git must be installed, and the pod must land on that node. Deprecation did not delete the feature. Restricted policy and removing the type are the controls."),
    q("ctr-images", "hard", "An image can be built so a pull calls out to an external URL. How did the maintainers treat it?", "As spec behavior, not a bug.", "As a critical bug, since fixed.", "As a registry-only issue.", "As blocked by signing.", "A pull is not a purely local operation. Know what a pull may do in your network. A registry mirror is also a place to see pulls."),
    q("obs-otel", "medium", "What are the three pieces of an OpenTelemetry setup for Kubernetes?", "Sources, a collector, and backends.", "Agents, a scraper, and dashboards.", "SDKs, a sidecar, and a log store.", "Exporters, a broker, and an index.", "The collector is the process you operate. If it is down, the backends go quiet while the cluster does not."),
    q("k8s-services", "easy", "What assigns pod IPs?", "The CNI plugin.", "The scheduler.", "kube-proxy.", "CoreDNS.", "'How does this packet get a pod IP' is a question about whichever plugin the cluster installed."),
    q("sec-least", "medium", "Why are long-lived credentials minted from a system account a persistence path?", "They keep working after the session ends.", "They let the holder escalate to cluster-admin.", "They are hidden from the API's audit log.", "They can be used without any RBAC binding.", "Static pods and extra tokens are the same class of problem: access that outlives the person. Review who can create tokens, certificates, and static pods."),
    q("k8s-rbac", "medium", "Why does SSRF via objects that make the API server call a URL matter?", "The API server calls from its network position.", "The API server forwards the caller's own token.", "Admission webhooks skip objects with URLs.", "Such objects are readable by any user.", "Creating those objects is a privileged action, and it should stay that way. The defensive control is who may create objects with URL fields."),
    q("k8s-workloads", "easy", "Why is letting a user create any Pod a security decision?", "The spec can ask for host access.", "Pods can read every namespace.", "Pods can bind cluster roles.", "Pods inherit the creator's RBAC.", "Host namespaces, privileged containers, and host paths are all fields. RBAC says who may create. Pod Security says what they may put in the spec."),
    q("k8s-workloads", "medium", "What is a DaemonSet that mounts the node's runtime socket?", "A root shell on every node.", "Safe if the mount is read-only.", "Limited to its own namespace.", "Safe under the baseline policy.", "The socket is the runtime's admin API, and read-only does not limit API calls. Do not grant create on DaemonSets to a tenant."),
    q("k8s-workloads", "medium", "You deploy redis as a Deployment with two replicas on port 6379. What keeps the replicas up?", "The ReplicaSet the Deployment owns.", "The Service in front of the pods.", "The kubelet's restartPolicy only.", "The HorizontalPodAutoscaler.", "A bare Pod would not be recreated. Namespace, Deployment, replicas, and container port are four fields. Missing one fails the check."),
    q("linux-files", "easy", "You need 0664 on files and 0775 on directories. Why is chmod -R 0664 wrong?", "It strips execute from directories.", "It makes the directories world-writable.", "It clears the owner of every file.", "It strips read from the group on files.", "Without execute you cannot traverse the directories. Set directory and file modes separately, for example with find -type d and -type f."),
    q("k8s-workloads", "easy", "Why is kubectl create cronjob the right kind?", "A CronJob creates Jobs on a schedule.", "A CronJob creates Pods with restarts.", "A CronJob runs a Deployment at times.", "A CronJob schedules a single Pod.", "The schedule is five cron fields. The command goes after --. kubectl run creates a Pod."),
    q("sec-pki", "easy", "What is a kubeconfig user entry built from a crt and a key?", "Client certificate authentication.", "A ServiceAccount token in disguise.", "An OIDC login with offline tokens.", "Basic auth stored in base64.", "The certificate is the identity. You still need a context and a role binding before kubectl can do anything useful."),
    q("iac-workflow", "easy", "Terraform enables versioning on an S3 bucket. What does that protect?", "Earlier copies of overwritten objects.", "The bucket itself from being deleted.", "Objects from public access.", "Objects from being read.", "Versioning is a flag on the bucket, off by default. It does not block public access or deletes of the bucket."),
    q("cloud-vpc", "easy", "A Terraform VPC uses 10.0.0.0/16 and a subnet 10.0.1.0/24. What else must hold?", "The subnet's CIDR is inside the VPC's.", "The subnet is in the default VPC too.", "The subnet has an internet gateway.", "The subnet's mask is larger than /16.", "The subnet is a slice of the VPC, and its dependency is the VPC ID. A CIDR outside the VPC will not create."),
    q("cloud-compute", "easy", "When is a Terraform EC2 instance actually running Amazon Linux 2?", "When its AMI ID is that image in that region.", "When instance_type is a t2 or t3 family.", "When it is tagged with the OS name.", "When no AMI is set, as that is the default.", "AMI IDs are regional. A hard-coded ID from a blog is often wrong or old. Look it up with a data source."),
    q("iac-ansible", "easy", "How should an Ansible playbook that installs Apache be built?", "Package and service modules, idempotent.", "A shell task running apt-get install.", "A script copied over and then run.", "A command task with ignore_errors.", "package and service modules check state first. The second run should change nothing if Apache is already correct."),
    q("cicd-actions", "medium", "A workflow tests a Flask app, builds an image, and pushes it. When is it broken?", "Failed tests still let the push run.", "The tests run in a container.", "The image is tagged with the SHA.", "It runs on every push to main.", "Fix the tests first. A green build of a failing test suite is the pipeline lying. Missing registry credentials and a broken Dockerfile are the other usual causes."),
    q("ctr-multistage", "easy", "When should a multi-stage Dockerfile fail review?", "The runtime stage still has the compiler.", "The runtime stage copies only one binary.", "The runtime stage uses a distroless base.", "The build stage uses a full SDK image.", "The point of the second stage is what you leave behind: compiler, source, and build credentials."),
    q("iac-modules", "medium", "A Terraform module should make the VPC pattern reusable. What should it expose?", "CIDR inputs and ID outputs.", "Its resources for callers to copy.", "A fixed CIDR and region inside.", "Its state file to other modules.", "If two environments differ only by variables, they should share the module. Callers should not copy the resource block."),
    q("ctr-compose", "medium", "When is an advanced Compose file with an app and database wrong?", "The app crashes because it starts too early.", "The app reaches the database by service name.", "The database has a named volume for data.", "Each service has its own Dockerfile.", "depends_on does not mean ready. Add a healthcheck condition, and put both services on a shared network."),
    q("cloud-sg", "medium", "What do baseline security setups on AWS, Azure, and GCP share?", "Least privilege, private storage, tight network rules.", "Encryption at rest, MFA, and logging for each user.", "A bastion, a VPN, and a WAF in front of each app.", "Separate accounts, regions and VPCs per team.", "Translate the control across clouds. Do not memorize three consoles and miss the idea."),
    q("cloud-iam", "easy", "A serverless to-do API runs on Lambda and DynamoDB. Where do the permissions go?", "On the Lambda's role, scoped to the table.", "On an IAM user whose keys the Lambda uses.", "On the API Gateway stage as a resource policy.", "On the DynamoDB table as a public policy.", "API Gateway is the front door. The function's role is the cloud permission, not an admin user key."),
    q("cicd-artifacts", "medium", "When is a broken test, build, and push pipeline actually fixed?", "Tests pass and the tested build is pushed.", "The image builds and pushes as latest.", "Tests are marked optional to unblock it.", "The image is built and pushed by hand.", "The registry tag should be the commit you tested, not a floating latest that overwrites yesterday's image."),
    q("cloud-compute", "hard", "A Lambda can't read its S3 bucket, and Terraform is already applied. What is it usually?", "The function's role or the bucket policy.", "The provider block's region setting.", "The bucket's versioning configuration.", "The Lambda's memory or timeout limit.", "A console fix would drift from the code, and the provider block is not the issue. The role and policy belong in Terraform."),
    q("ctr-debug", "medium", "A Compose stack that used to work now fails. How do you debug it?", "Find the exited service and read its logs.", "Rebuild everything with --no-cache first.", "Prune volumes and networks, then retry.", "Restart the Docker daemon and retry.", "One exited container with a log line is the usual answer. The rest of the stack is waiting on it. Then check what changed, such as a port or volume path."),
    q("obs-metrics", "easy", "A Linux monitoring script prints CPU once. What else does it need?", "A schedule, failure logging, and thresholds.", "Root access, so it sees every process.", "A graph library to plot the samples.", "A faster sampling rate, under one second.", "Cron plus a silent failure is how a disk fills up unseen. Someone has to look at the threshold."),
    q("k8s-gitops", "easy", "When is Argo CD the right tool?", "The manifests are in git and a controller applies them.", "The manifests are on a laptop and applied by hand.", "The images need building when a commit lands.", "The cluster's state needs backing up to git.", "The Application points at a repo and a path. Drift from a manual edit gets corrected."),
    q("iac-workflow", "medium", "Terraform creates a Kubernetes cluster. Where should the cluster credentials be kept?", "Out of committed state and out of git.", "In a sensitive output, which hides them.", "In terraform.tfvars, next to the code.", "In the CI log, where admins can find them.", "Sensitive outputs are still in state. The cluster is cattle. The kubeconfig is a key."),
    q("k8s-services", "medium", "What is Istio next to a Kubernetes service for?", "mTLS and routing rules between pods.", "Load balancing that replaces Services.", "DNS for pods across namespaces.", "Autoscaling pods on request rate.", "The Deployment still runs the container. If you turn on strict mTLS, clients outside the mesh stop working until you intend that."),
    q("iac-policy", "easy", "Why does OPA fail an apply when the S3 bucket is public?", "The policy is evaluated against the plan.", "AWS rejects public buckets by default.", "OPA reads the bucket ACL after apply.", "Rego runs as an S3 bucket policy.", "Versioning and block-public-access are two rules. Either one failing should stop Terraform."),
    q("cloud-compute", "medium", "What does Packer followed by Terraform mean?", "Bake Nginx into an AMI, then launch it.", "Terraform installs Nginx over SSH.", "Packer launches the instances it bakes.", "Each boot rebuilds the AMI from scratch.", "Replace the instance to patch. Do not patch the running one and call it immutable."),
    q("sec-vault", "easy", "Why should an app read its password from Vault at start?", "So it is not in the Terraform or the image.", "So Vault can rotate the root token often.", "So the app can cache it in a ConfigMap.", "So the password is versioned in git.", "The app authenticates to Vault for that one path, with a lease that expires. Not root."),
    q("iac-modules", "hard", "Moving resources between modules will destroy them unless what?", "A moved block or state mv for each.", "A matching name in the new module.", "A refresh before the next plan.", "A depends_on on the old module.", "Addresses are identity. The plan that says destroy on a database is the review that matters."),
    q("obs-alerts", "medium", "When is a chaos experiment useful?", "You break one thing and alerts and fallback work.", "You break things at random to find weak spots.", "You test it once in staging, then sign it off.", "You mute alerts so the team is not woken up.", "The point is the detection and the recovery, not the outage. Break something specific with a signal and a rollback ready."),
    q("obs-prometheus", "easy", "Why are Prometheus and Grafana usually paired?", "Prometheus stores. Grafana draws.", "Grafana stores. Prometheus draws.", "Prometheus pages. Grafana logs.", "Grafana scrapes. Prometheus alerts.", "An alert also needs a rule and a route, not only a chart. If nobody is paged, the chart is a souvenir."),
    q("cloud-lb", "medium", "Traefik on ECS is the edge router. When does it fail?", "The target group, task port or SG don't match.", "The ECS task has a container HEALTHCHECK.", "The service runs more than one task.", "The Traefik config uses Docker labels.", "The route, the task, and the security group are three configs that must agree."),
    q("iac-ansible", "medium", "Why should network automation with Ansible be idempotent?", "Reruns must not flap correct rules.", "Network modules cannot run twice.", "Devices reboot when config changes.", "Ansible caches facts between runs.", "A playbook that appends a rule every run will lock you out eventually."),
    q("k8s-secrets", "medium", "An app with a database password also gets an HPA. What is still required?", "The password injected from a Secret.", "The HPA mounting the Secret for pods.", "The password set in the Deployment.", "A ConfigMap holding the password.", "HPA changes replica count, not how the secret is injected. The Service must also select the pods."),
    q("ctr-compose", "easy", "What is a multi-service Compose stack about?", "Several services, a network, durable data.", "One container, a port, a health check.", "Building images on every compose up.", "Running the stack under Kubernetes.", "Name the volume if the database files matter."),
    q("iac-ansible", "hard", "Why test an Ansible role with Molecule?", "It converges and verifies in a throwaway VM.", "It lints the YAML and the Jinja templates.", "It runs the role in check mode on the fleet.", "It records which hosts the role changed.", "A broken task fails before it hits the fleet. A role you only ran once on a laptop is untested."),
    q("k8s-helm", "medium", "What does packaging a service as a Helm chart mean?", "Templates plus values for each deploy.", "One manifest with hard-coded settings.", "An image with its manifests baked in.", "A Kustomize base with overlays.", "Override a community chart with a values file. You do not fork the chart for one replica count."),
    q("k8s-helm", "hard", "What do Helmfile plus a migration hook give you?", "Declared releases, with migrations in the release.", "One chart that deploys to all clusters at once.", "Automatic rollback when a migration fails.", "Migrations run once per chart version only.", "One file describes dev, staging and prod releases, and the migration runs as a hook rather than a manual job someone hopes ran."),
    q("linux-shell", "medium", "A bash installer asks which database and web server to install. What does it need?", "Error checks and a dry-run mode.", "A trap that ignores every error.", "A rewrite in Python for safety.", "A reboot after each install step.", "set -euo pipefail or explicit checks, and a dry run that prints commands. A second run should not break a working Apache."),
    q("cicd-runners", "easy", "What is Tilt for local microservices?", "A dev loop that rebuilds on file change.", "A CI service for running test suites.", "A local Kubernetes distribution.", "A tool for deploying to production.", "The Tiltfile wires frontend, backend, and database. Live reload is the point. Production still wants a pipeline."),
    q("net-tunnels", "medium", "Why is the jump host hardened and minimal?", "Every production login passes through it.", "It holds the private keys for production.", "It runs the production monitoring stack.", "It is the only host with internet access.", "Extra services on it are extra ways in. Access is a playbook run, both to add and to remove keys."),
    q("sec-secrets", "hard", "When is a MySQL backup to S3 incomplete?", "When the restore was never tested.", "When the dump is compressed first.", "When it runs from a cron schedule.", "When it uses mysqldump, not a snapshot.", "Encrypt, upload, log, and rehearse the restore. The restore script is part of the backup."),
    q("iac-ansible", "easy", "What do a Puppet master and agent do on a fleet?", "Agents check in and converge to the manifest.", "The master pushes SSH commands to agents.", "Agents report state, and admins fix drift.", "The master builds images for the agents.", "The manifest is the standard build. A second run does not keep changing a correct host."),
    q("iac-workflow", "medium", "When does Terratest fail a change?", "Assertions fail on the real resources it applied.", "terraform validate finds a syntax error first.", "The plan shows resources being replaced.", "tflint finds an unused variable.", "Terratest applies the Terraform in a test account and checks real resources. Destroy them at the end. A test that leaves a VPC running is a bill."),
    q("sec-pipeline", "medium", "What does shift-left mean in a secure SDLC?", "Checks run on each change in the pipeline.", "Security reviews move to the design phase only.", "Developers own security and skip review.", "Scans run nightly instead of at release.", "The checkpoint has to be able to fail the build. A report nobody gates on is not a checkpoint."),
    q("sec-pipeline", "easy", "How do SAST and SCA in a pipeline differ?", "SAST reads your code. SCA reads dependencies.", "SAST reads dependencies. SCA reads your code.", "SAST runs the app. SCA reads the source.", "SAST scans images. SCA scans the code.", "Running the app is DAST. An image scan is a third pass, over the OS packages in the image."),
    q("sec-threat", "easy", "What does a threat model ask before you choose a tool?", "What to protect, from whom, across which boundary.", "Which tools fit your budget and your stack.", "Which compliance controls the auditors want.", "Which CVEs affect the current release.", "The tool is how you check one of the answers."),
    q("ctr-security", "medium", "What does splitting container security into build, ship, and run mean?", "No single scan catches every stage's mistakes.", "Each stage is owned by a separate team.", "Each stage runs the same scanner again.", "Only the run stage needs its own separate policy.", "A Dockerfile mistake, a registry mistake, and a running-pod mistake differ. Pin the digest you scanned, admit only that digest, and watch the process."),
    q("k8s-workloads", "easy", "Why does Kubernetes security start from reconciliation?", "Controllers keep recreating whatever the spec says.", "Controllers fix bad specs before pods are made.", "Controllers only act when kubectl apply runs.", "Controllers roll back pods that fail probes.", "A bad spec is reapplied until admission rejects it, and kubectl edit against a controller does not stick."),
    q("sec-zero", "medium", "Why does workload identity replace a copied kubeconfig?", "Each pod authenticates as itself, briefly.", "The kubeconfig cannot be mounted in a pod.", "Workload identity skips RBAC for pods.", "The node's identity is shared with pods.", "RBAC is written for that identity, with short-lived tokens. Network policy limits who can talk. Identity limits who the API believes."),
    q("cloud-compute", "medium", "Why do serverless permission boundaries matter?", "The function role is all the code should hold.", "Functions cannot be given IAM roles.", "Functions run as the account's root user by default.", "API Gateway policies replace the role.", "A too-wide role turns one bug into every bucket. Keep the event source narrow too."),
    q("sec-bench", "easy", "How do kube-hunter and kube-bench differ?", "Hunter probes for attack paths. Bench checks CIS.", "Hunter checks CIS. Bench probes for attack paths.", "Hunter scans images. Bench scans manifests.", "Hunter audits RBAC. Bench audits network policy.", "Do not point an active probe at a cluster you do not own."),
    q("obs-alerts", "easy", "What is ElastAlert for?", "It runs rules over a log store and notifies.", "It ships logs from hosts into Elasticsearch.", "It evaluates Prometheus alert expressions.", "It routes alerts from many sources to on-call.", "It does not collect the logs. A rule with no route is silent, and a route with no owner is noise."),
    q("sec-secrets", "medium", "Conjur, CredStash, Blackbox, SOPS, and Transcrypt are all secrets tools. How do they differ?", "Some encrypt files in git. Some are services.", "Some rotate keys. Others store certificates.", "Some run in Kubernetes. Others run on hosts.", "Some use KMS. Others use PGP for every file.", "A file cipher is not a lease. Pick a service when many workloads need rotation, and a file cipher when git must hold ciphertext."),
    q("sec-audit", "easy", "How do OSSEC and Wazuh differ from kube-bench?", "They watch hosts continuously for events.", "They scan Kubernetes manifests for flaws.", "They review cluster config once, on demand.", "They enforce admission policy in clusters.", "Bench is a point-in-time config review. A host agent does not see the Kubernetes API audit log. You still want both."),
    q("obs-logs", "easy", "Arkime (formerly Moloch) stores packet captures. When is it the wrong tool?", "Finding who called the Kubernetes API.", "Finding what a suspicious host sent out.", "Finding the packets behind a slow request.", "Finding a flow the flow logs missed.", "API calls are in the audit log, not a pcap. Capture is heavy, so turn it on for a question, with a retention limit."),
    q("sec-image", "medium", "Microscanner or Snyk gives a green result. What is still needed?", "The scanned digest to be the deployed one.", "A second scanner to confirm the result.", "A rescan after the pods are running.", "A signature from the scanner's vendor.", "Someone also has to own any finding. SCA, image scan, and host scan see different inventories."),
    q("iac-policy", "easy", "What is Deepfence ThreatMapper closer to?", "A view of deployed assets and attack paths.", "A Terraform plan linter with policies.", "A pre-commit hook for secret detection.", "An admission controller for pod specs.", "Checkov sees the code. ThreatMapper sees what is deployed. Drift lives between them."),
    q("sec-incident", "medium", "What is StackStorm for in security automation?", "Triggering scripted actions from events.", "Storing incident timelines and notes.", "Paging on-call engineers by schedule.", "Collecting forensic images from hosts.", "The action is only as safe as the credentials it holds. An automation that can quarantine a host is an admin. Scope it and log it."),
    q("obs-metrics", "easy", "Grafana and Kibana are dashboards over different stores. Which pairing is typical?", "Grafana on metrics, Kibana on Elasticsearch.", "Grafana on Elasticsearch, Kibana on metrics.", "Grafana on traces, Kibana on Prometheus.", "Grafana on logs, Kibana on InfluxDB.", "Grafana can read many sources, but metrics are its home. A dashboard is not the retention policy of the store behind it."),
    q("sec-secrets", "easy", "What does git-secrets block, and what does it not do?", "New commits with keys, not old history.", "Pushes with keys, and it rewrites history.", "Old history, but not new commits.", "Key files, but not keys in code.", "Run it as a hook before the push. After the push, rotate."),
]
